// Read-only preflight. Run before creating a new sparse worktree.
const {execFileSync}=require('node:child_process');
const fs=require('node:fs');
const [ref,capText,...paths]=process.argv.slice(2);
const cap=Number(capText),floor=2210398208;
if(!ref||!Number.isSafeInteger(cap)||cap<=0||!paths.length)throw Error('usage: node sparse-preflight.cjs REF TOTAL_EXPANSION_CAP_BYTES EXACT_FILE...');
if(paths.some(p=>!p||p.startsWith('/')||p.split('/').some(x=>x==='..'||x==='.')||/[\n\r*?\[\]\\!]/.test(p)))throw Error('Only literal repository-relative file paths permitted');
const git=(...a)=>execFileSync('git',a,{encoding:'utf8'}).trim();
const commit=git('rev-parse','--verify',ref+'^{commit}');
const files=paths.map(path=>{const object=git('rev-parse',commit+':'+path);if(git('cat-file','-t',object)!=='blob')throw Error('Not a file: '+path);return {path,object,bytes:Number(git('cat-file','-s',object))};});
const projectedFiles=files.reduce((n,f)=>n+Math.ceil(Math.max(1,f.bytes)/4096)*4096,0);
const reserve=2*1024*1024; // minimum metadata room, not a measured upper bound
const stat=fs.statfsSync('.');const available=stat.bavail*stat.bsize;
const pass=projectedFiles+reserve<=cap&&available-cap>=floor;
console.log(JSON.stringify({pass,commit,files,projectedFiles,minimumMetadataReserve:reserve,totalExpansionCap:cap,available,floor,remainingAtCap:available-cap,notes:'Cap must also cover Git objects, tests and evidence; recheck disk and actual materialized paths after checkout.'},null,2));
if(!pass)process.exitCode=1;
